(function(){
'use strict';
const G=PatternGenetics,S=PatternSumo,P=PatternSumoStage,B=PatternBeetles,A=PatternLabApp,$=id=>document.getElementById(id);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let match=null,paused=false,acc=0,lastFrame=0,playback=1,participants=null,connection=null,pollTimer=null,pollBusy=false,seenMatch=0,lastLogged=null,celebrating=false,partyStarted=0,partyShared=false,partyFinished=false,startPending=false;
const sharedClock=P.createClock();
const roomSpeed=()=>P.sharedSpeed(connection?.room);
const arenaArt=(b,prefix)=>B.draw(b,prefix)+'<i class="flip-belly" aria-hidden="true"></i>';
function syncStartButton(){$('room-start').disabled=!!startPending||connection?.role!=='host'||!connection.room?.guest||!!(match?.shared&&!match.done);}
function resetCelebration(){celebrating=false;partyStarted=0;partyShared=false;partyFinished=false;$('sumo-celebration').hidden=true;$('sumo-confetti').replaceChildren();for(const id of ['fighter-a','fighter-b'])$(id).classList.remove('victor','victory-dance','defeated','airborne','lifted','dizzy','winding-lift','winding-jump','winding-puff','move-lift','move-jump','move-puff','flipped');}
function celebrate(){
 if(celebrating||match.winner===null)return;celebrating=true;partyShared=!!(match.shared&&connection?.room?.startedAt);
 const elapsed=partyShared?P.victoryElapsed(sharedClock.now(),connection.room.startedAt,match.time,roomSpeed()):0;
 partyStarted=partyShared?Date.parse(connection.room.startedAt)+match.time*1000/roomSpeed():performance.now();
 const winningId=match.winner?'fighter-b':'fighter-a',losingId=match.winner?'fighter-a':'fighter-b';
 $(winningId).classList.add('victor');$(losingId).classList.add('defeated');
 const own=match.shared&&connection&&(connection.role==='host'?0:1)===match.winner;
 $('victory-title').textContent=own?'Your beetle wins!':(match.winner?'Blue':'Red')+' wins!';
 $('victory-caption').textContent=(match.winner?'Blue':'Red')+' corner · victory dance';
 $('sumo-celebration').hidden=false;
 if(elapsed<6000){$(winningId).style.setProperty('--victory-delay',-elapsed+'ms');$(winningId).classList.add('victory-dance');
  const fragment=document.createDocumentFragment();for(const p of P.confetti(match.seed,match.winner)){const bit=document.createElement('i');bit.className='confetti-bit'+(p.round?' round':'');bit.style.cssText=`left:${p.left}%;--drift:${p.drift}px;--turn:${p.turn}deg;background:${p.color};animation-duration:${p.duration}ms;animation-delay:${p.delay-elapsed}ms`;fragment.append(bit);}$('sumo-confetti').append(fragment);
 }
}
function updateCelebration(){if(!celebrating||partyFinished)return;const elapsed=(partyShared?sharedClock.now():performance.now())-partyStarted;if(elapsed>=6000){partyFinished=true;$('sumo-confetti').replaceChildren();for(const id of ['fighter-a','fighter-b'])$(id).classList.remove('victory-dance');$('victory-caption').textContent=(match.winner?'Blue':'Red')+' corner · ready for a rematch';}}
const descriptions={tracking:'How accurately a beetle aims at a moving opponent.',reaction:'How often it reconsiders its direction.',focus:'How reliably it keeps attending to its opponent.',pushDrive:'The tendency to approach and push instead of exploring.',wander:'The tendency to choose a wandering path. It can interrupt a promising push.',turnRate:'How quickly it turns. High mass and very fast running make sharp turns harder.',tactics:'Game intelligence: predicts movement and sometimes circles toward the inside of the ring before pushing outward.',edgeSense:'How often it notices the boundary and turns inward.',brace:'How firmly it supports a head-on push. Settling into a brace also slows turning during contact.',lateralBalance:'Resistance to being moved by a side push.',grip:'How effectively feet transfer force to the table. It helps pushing and resisting a shove.',endurance:'How slowly pushing effort drains its available energy.',recovery:'How quickly it regains energy while not pushing; also helps resist rear pushes.',mass:'Heavier beetles resist changes in movement and off-center shoves, but accelerate and turn more slowly.',acceleration:'How quickly it builds up walking speed.',centerDrive:'How strongly exploratory paths favor the middle.',curiosity:'How often wandering changes into an approach.',sociality:'How much it approaches nearby beetles in the breeder tank.',caution:'How much it helps edge awareness override a risky path.',persistence:'How likely it is to keep pursuing an ongoing push.'};
Object.assign(descriptions,{liftPower:'Lift strength combines horn reach and positioning. A wind-up weakens pushing; a lift briefly reduces the other beetle’s grip. A higher lift has a greater chance of flipping the opponent. Flipped beetles cannot push and have low resistance until they right themselves; recovery, legs and body build affect that time. Short horns, low bodies, strong grip and bracing reduce its effect. Side approaches can make it miss.',jumpPower:'A spring joint must be inherited to jump. Jumps can escape a lift or puff; the beetle cannot push while airborne. Landing control, edge awareness and stamina matter. A risky jump can go out of bounds.',puffPower:'A puff gland must be inherited. Two cartoon puffs per match can briefly scramble an opponent’s aim and pushing. Range and facing matter; jumping can dodge a puff. Both charges return in the next match. These are invented harmless game rules.'});
function display(b,fallback='Beetle'){return b?.name?b.name+' · '+b.id:b?.id||fallback;}
function download(filename,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function picked(){const s=A.getState();return [s.beetles[$('sumo-a').value],s.beetles[$('sumo-b').value]];}
function players(){return connection&&participants?participants:picked();}
function refresh(){const s=A.getState();$('sumo-section').hidden=s.settings.allowSumo===false;$('specimen-red').hidden=s.settings.allowSumo===false;$('specimen-blue').hidden=s.settings.allowSumo===false;
 for(const [id,index] of [['sumo-a',0],['sumo-b',1]]){const select=$(id),old=select.value;select.innerHTML=Object.values(s.beetles).map(b=>`<option value="${b.id}">${esc(display(b))} · Gen ${b.lineageGeneration}${s.collection.includes(b.id)?' · kept':''}</option>`).join('');select.value=s.beetles[old]?old:Object.keys(s.beetles)[index]||'B1';select.disabled=!!connection;}
 $('sumo-start').disabled=!!connection||picked().some(b=>!b);$('compare-open').disabled=players().some(b=>!b);if(connection)connectionUI();else if(!match)preview();
}
function preview(){resetCelebration();const [a,b]=picked();if(!a||!b){for(const id of ['fighter-a','fighter-b'])$(id).innerHTML='';return;}participants=[a,b];$('fighter-a').innerHTML=arenaArt(a,'arena-a');$('fighter-b').innerHTML=arenaArt(b,'arena-b');$('fighter-a').style.transform='translate(-50%,-50%) rotate(90deg)';$('fighter-b').style.transform='translate(-50%,-50%) rotate(-90deg)';$('fighter-a').style.left='33%';$('fighter-b').style.left='67%';$('sumo-ring').classList.remove('legacy-ring');for(const id of ['fighter-a','fighter-b'])$(id).style.top='50%';$('sumo-ring').classList.add('resting');}
function newMatch(list,seed,shared=false,version='SUMO7'){resetCelebration();participants=list.map(G.clone);match=S.create(participants[0],participants[1],seed,{version});match.shared=shared;$('sumo-ring').classList.toggle('legacy-ring',!['SUMO4','SUMO5','SUMO6','SUMO7'].includes(match.version));paused=false;acc=0;lastLogged=null;$('fighter-a').innerHTML=arenaArt(participants[0],'arena-a');$('fighter-b').innerHTML=arenaArt(participants[1],'arena-b');$('sumo-pause').disabled=shared;$('sumo-pause').textContent='Pause match';$('sumo-ring').classList.remove('resting');$('ring-countdown').hidden=true;$('sumo-ring').scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});$('sumo-result').textContent=shared?'Friend battle at '+roomSpeed()+'× — both screens share the same moves and result.':'A fresh match. Watch the approach and the pushing angles.';}
function drawMatch(){if(!match)return;for(const [i,id] of ['fighter-a','fighter-b'].entries()){const f=match.fighters[i];$(id).style.left=(50+f.x/480*100)+'%';$(id).style.top=(50+f.y/480*100)+'%';$(id).style.transform=`translate(-50%,-50%) rotate(${f.heading+Math.PI/2}rad)`;for(const name of ['lift','jump','puff']){$(id).classList.toggle('winding-'+name,f.action?.move===name);$(id).classList.toggle('move-'+name,!match.done&&f.lastMove?.move===name&&match.time-f.lastMove.time<2);}
 $(id).classList.toggle('flipped',!match.done&&f.flipped>0);
 $(id).classList.toggle('airborne',!match.done&&f.air>0);$(id).classList.toggle('lifted',!match.done&&f.lifted>0);$(id).classList.toggle('dizzy',!match.done&&f.dizzy>0);
 $(id).style.setProperty('--hop',f.air>0?Math.sin(Math.PI*f.air/f.airTotal):0);
 $(i?'blue-behavior':'red-behavior').textContent=(i?'Blue: ':'Red: ')+f.mode;}
 $('center-status').textContent='Distance from center · red '+Math.round(100*Math.hypot(match.fighters[0].x,match.fighters[0].y)/match.radius)+'% · blue '+Math.round(100*Math.hypot(match.fighters[1].x,match.fighters[1].y)/match.radius)+'%';
 $('sumo-clock').textContent=Math.floor(match.time/60)+':'+String(Math.floor(match.time%60)).padStart(2,'0');
 if(match.done){celebrate();$('sumo-ring').classList.add('resting');$('sumo-pause').disabled=true;const winner=match.winner===null?'A draw':(match.winner===0?'Red':'Blue')+' wins';const side=match.events.filter(e=>e.side==='side').length,rear=match.events.filter(e=>e.side==='rear').length,wandering=match.fighters.map(f=>Math.round(f.wanderingTime));$('sumo-result').textContent=winner+' · '+match.reason+(match.centerDistances?' (red '+match.centerDistances[0].toFixed(3)+', blue '+match.centerDistances[1].toFixed(3)+' from center)':'')+'. Side contacts: '+side+'; rear contacts: '+rear+'. Wandering: red '+wandering[0]+'s, blue '+wandering[1]+'s.'+(match.flips?.length?' Flips: red '+match.flips.filter(e=>e.actor===0).length+', blue '+match.flips.filter(e=>e.actor===1).length+'.':'')+(match.abilities?.length?' Adaptations: '+match.abilities.map(e=>(e.actor?'Blue':'Red')+' '+G.abilityNames[e.move]+(e.hit?' ✓':' missed')).join('; ')+'.':'');
  const key=match.seed+'-'+match.tick+'-'+(connection?.code||'local');if(lastLogged!==key){lastLogged=key;const state=A.getState();state.matchHistory=state.matchHistory||[];if(!state.matchHistory.some(r=>r.seed===match.seed&&r.fighters.map(f=>f.genomeFingerprint).join('|')===S.record(match).fighters.map(f=>f.genomeFingerprint).join('|')))state.matchHistory.push({...S.record(match),participants:match.fighters.map(f=>G.packet(f.beetle)),source:match.shared?'shared':'local',recordedAt:new Date().toISOString()});state.matchHistory=state.matchHistory.slice(-100);A.save();}
  if(connection?.role==='host')syncStartButton();
 }
}
function animate(now){const dt=Math.min(.15,(now-lastFrame)/1000||0);lastFrame=now;
 if(match&&!match.done){
  if(match.shared&&connection?.room?.startedAt){const serverNow=sharedClock.now(),elapsed=(serverNow-Date.parse(connection.room.startedAt))/1000;$('ring-countdown').hidden=elapsed>=0;$('ring-countdown').textContent=elapsed<0?String(Math.ceil(-elapsed)):'';const target=P.targetTick(serverNow,connection.room.startedAt,match.maxSeconds,roomSpeed());while(!match.done&&match.tick<target)S.step(match);}
  else if(!paused&&!document.hidden){acc+=dt*playback;let count=0;while(acc>=1/60&&count++<100){S.step(match);acc-=1/60;if(match.done)break;}}
  drawMatch();
 }
 updateCelebration();
 requestAnimationFrame(animate);
}
function traitCard(b,index){const p=G.phenotype(b);return `<div class="compare-beetle"><h3>${index?'Blue corner':'Red corner'} · ${esc(display(b))}</h3>${B.draw(b,'compare'+index)}<p>${G.antennaNames[p.antenna]} · ${G.legNames[p.leg]}<br>${p.visibleLayers} visible pattern ${p.visibleLayers===1?'color':'colors'}</p>${A.getState().settings.showStats?Object.keys(descriptions).map(k=>`<div class="trait-meter"><span>${G.byKey[k].label}</span><meter min="0" max="1" value="${p[k]}">${Math.round(p[k]*100)}%</meter><b>${Math.round(p[k]*100)}</b></div>`).join(''):`<div class="traits">${G.observationTags(b).map(word=>`<span class="trait clue">${word}</span>`).join('')}</div><p class="hint">Field marks are clues. Observe walking, breeding and contests to discover their meaning.</p>`}</div>`;}
function compare(){const list=players();if(list.some(b=>!b))return;$('comparison-content').innerHTML=list.map(traitCard).join('');$('comparison').showModal();}
function allele(a,l){return l.type==='number'?a.toFixed(3):l.type==='color'?'RGB '+a.rgb.join(', ')+'; expression '+a.expression.toFixed(3):a.value+'; expression '+a.expression.toFixed(3);}
function exportBeetle(documentMode){const b=A.getState().beetles[A.getSelected()];if(!b)return;const packet=G.packet(b),json=JSON.stringify(packet,null,2),base='Pattern-Lab-'+b.id;
 if(!documentMode){download(base+'.json',json);A.toast('Beetle JSON exported. Import beetle file adds it to any compatible tank.');return;}
 const p=G.phenotype(b),html=`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(display(b))} — Beetle record</title><style>body{font:15px/1.6 system-ui;color:#254b3e;max-width:960px;margin:40px auto;padding:25px}h1,h2{font-family:Georgia}svg{float:right;width:270px;height:340px;background:#edf1df;border-radius:20px}table{border-collapse:collapse;width:100%;font-size:12px}td,th{padding:7px;border:1px solid #dae1d2;text-align:left}h2{clear:both;padding-top:20px}.leg-swing{animation:none}button{padding:10px 16px}@media print{button{display:none}table{break-inside:auto}tr{break-inside:avoid}body{margin:0}}</style><h1>${esc(display(b))}</h1><p>Leaf &amp; Lineage · Pattern Lab v2 · Portable beetle record</p>${B.draw(b,'document')}<p>Lineage generation ${b.lineageGeneration}<br>Parents: ${b.parents.map(esc).join(', ')||'Founder or externally recorded ancestry'}<br>${G.antennaNames[p.antenna]} antennae · ${G.legNames[p.leg]}<br>${p.visibleLayers} visible pattern colors${A.getState().settings.showStats?' · speed '+p.speed+' · strength '+p.strengthIndex+'/100':' · Field marks: '+G.observationTags(b).join(' · ')}</p><p>This HTML document embeds the full genetic packet. Use <strong>Import beetle file</strong> to re-upload this document or its JSON counterpart. Printing a PDF creates a readable report; use HTML or JSON to restore the beetle.</p><button onclick="window.print()">Print / save as PDF</button>${A.getState().settings.showStats?`<h2>Paired gene copies and quantitative contributions</h2>${G.chromosomes.map(c=>`<h3>Chromosome ${c.id}</h3><table><thead><tr><th>Trait</th><th>Copy 1</th><th>Copy 2</th></tr></thead><tbody>${c.loci.map(l=>{const cp=G.copies(b,l.key);return `<tr><td>${l.label}</td><td>${esc(allele(cp[0],l))}</td><td>${esc(allele(cp[1],l))}</td></tr>`;}).join('')}</tbody></table>`).join('')}`:''}<p>Invented teaching genetics and game traits, not measured real-species biology. Development seed ${b.developmentSeed}; genotype fingerprint ${G.checksum(JSON.stringify(b.genome)+b.developmentSeed)}.</p><script type="application/json" id="pattern-beetle-data">${json.replace(/</g,'\\u003c')}</script></html>`;
 download(base+'.html',html,'text/html');A.toast('Printable beetle document exported, with embedded data for re-upload.');
}
function parseFile(text){const trimmed=text.trim();if(trimmed.startsWith('{'))return G.validatePacket(JSON.parse(trimmed));const found=text.match(/<script type="application\/json" id="pattern-beetle-data">([\s\S]*?)<\/script>/);if(!found)throw Error('Choose a beetle JSON or an exported beetle HTML document.');return G.validatePacket(JSON.parse(found[1]));}
function family(){const s=A.getState(),id=A.getSelected();if(!s.beetles[id])return;function branch(key,depth,path){const b=G.record(s,key);if(!b)return '<span>External ancestry</span>';if(path.includes(key))return '<span>Repeated ancestor</span>';return `<div class="tree-node"><button data-tree="${b.id}" ${s.beetles[key]?'':'disabled'}>${b.genome||b.appearance?B.draw(b,'family-'+depth+'-'+path.join('-')):'<span class="missing-portrait" aria-hidden="true">♧</span>'}<span>${esc(display(b))}</span><small>Generation ${b.lineageGeneration}${s.beetles[key]?'':' · '+esc(b.reason)}${!b.genome&&!b.appearance?' · appearance not recorded':''}</small></button>${b.provenance?'<small>Imported · source '+esc(b.provenance.sourceId)+'</small>':''}${depth<3&&b.parents.length?'<div class="tree-parents">'+b.parents.map(p=>branch(p,depth+1,[...path,key])).join('')+'</div>':''}</div>`;}$('family-tree-content').innerHTML=branch(id,0,[]);$('family-tree').showModal();}
function log(){const rows=A.getState().matchHistory||[];$('match-log-content').innerHTML=rows.slice().reverse().map((m,i)=>`<article class="history-item"><strong>${esc(m.winner===null?'Draw':m.winner===0?'Red won':'Blue won')} · ${m.seconds}s</strong><p>${esc(m.reason)}${m.centerDistances?' · center distances red '+m.centerDistances[0].toFixed(3)+', blue '+m.centerDistances[1].toFixed(3):''} · ${m.source==='shared'?'Shared table':'Local table'}${m.flips?.length?'<br>Flips: '+m.flips.map(e=>esc((e.actor?'Blue':'Red')+' flipped '+(e.defender?'blue':'red')+' at '+e.time+'s; recovery '+e.duration+'s')).join(' · '):''}${m.abilities?.length?'<br>Adaptations: '+m.abilities.map(e=>esc((e.actor?'Blue':'Red')+' '+G.abilityNames[e.move]+(e.hit?' succeeded':' missed')+' at '+e.time+'s')).join(' · '):''}<br>${m.fighters.map((f,j)=>(j?'Blue':'Red')+': '+esc(f.name||f.id)+' · wandering '+f.wanderingSeconds+'s · side pushes '+f.sidePushes).join('<br>')}</p><button data-replay="${rows.length-1-i}">Replay recorded match</button></article>`).join('')||'<p>No completed matches yet. Make a prediction before your first contest.</p>';$('match-log').showModal();}
function secureToken(){const bytes=crypto.getRandomValues(new Uint8Array(32));return btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
async function request(action,payload){const cfg=globalThis.PatternSharingConfig;if(!cfg?.url)throw Error('Online rooms are not configured. Local sumo and beetle files still work.');const sent=performance.now(),response=await fetch(cfg.url,{method:'POST',headers:{'Content-Type':'application/json',apikey:cfg.publishableKey},body:JSON.stringify({action,model:connection?.room?.physicsVersion||P.sharedModel($('room-speed').value),...payload}),signal:AbortSignal.timeout(15000)});let data;try{data=await response.json();}catch{throw Error('The sharing service did not respond. Try again shortly.');}if(!response.ok)throw Error(data.error||'Could not connect to that table.');if(data.room?.serverNow)sharedClock.sample(data.room.serverNow,sent,performance.now());return data;}
function connectionUI(){const active=!!connection;$('sumo-a').disabled=active;$('sumo-b').disabled=active;$('sumo-start').disabled=active;$('room-create').disabled=active;$('room-join').disabled=active;$('room-code-box').hidden=!active;$('room-leave').hidden=!active;$('room-start').hidden=!active||connection.role!=='host';$('sumo-speed').disabled=active;$('room-speed').disabled=active;if(active){$('room-code').value=connection.code.slice(0,4)+'-'+connection.code.slice(4);$('sumo-a').selectedOptions[0].textContent='Shared host beetle · red corner';$('sumo-b').selectedOptions[0].textContent=connection.room?.guest?'Shared visitor beetle · blue corner':'Waiting for a visitor';$('room-speed').value=String(roomSpeed());$('sumo-speed').value=String(roomSpeed());playback=roomSpeed();}syncStartButton();}
function persistConnection(){try{if(connection)sessionStorage.setItem('pattern-sumo-connection',JSON.stringify({code:connection.code,token:connection.token,role:connection.role}));else sessionStorage.removeItem('pattern-sumo-connection');}catch{}}
function applyRoom(room){if(!connection||!P.acceptRoom(connection.code,Math.max(seenMatch,connection.room?.matchNumber||0),room))return;if(!P.supportedRoom(room))throw Error('Open the latest lab on both screens and create a new challenge code.');connection.room=room;participants=[G.validatePacket(room.host).beetle,room.guest?G.validatePacket(room.guest).beetle:null];
 $('room-status').textContent=room.guest?(connection.role==='host'?'A visitor’s beetle has arrived. Start the shared match.':'Your beetle is on the blue side. Waiting for the host to start.'):'Code ready. Waiting for a second screen to send a beetle.';
 if(room.guest&&room.matchNumber>seenMatch&&room.startedAt){seenMatch=room.matchNumber;newMatch(participants,room.seed,true);$('room-status').textContent='Shared match '+room.matchNumber+' · synchronized countdown and matching moves at '+roomSpeed()+'×.';}
 if(room.matchNumber>0)$('room-status').textContent=match?.done?'Shared match '+room.matchNumber+' finished. The host can start a rematch.':'Shared match '+room.matchNumber+' · both screens replay the same physics at '+roomSpeed()+'×.';
 connectionUI();
 if(!match){$('fighter-a').innerHTML=arenaArt(participants[0],'shared-a');$('fighter-b').innerHTML=participants[1]?arenaArt(participants[1],'shared-b'):'';for(const [i,id] of ['fighter-a','fighter-b'].entries()){$(id).style.left=(i?67:33)+'%';$(id).style.top='50%';$(id).style.transform='translate(-50%,-50%) rotate('+(i?-90:90)+'deg)';}$('sumo-ring').classList.add('resting');}
}
async function poll(){if(!connection||pollBusy||document.hidden)return;const active=connection;pollBusy=true;try{const data=await request('read',{code:active.code,token:active.token});if(connection===active)applyRoom(data.room);}catch(e){if(connection!==active)return;$('room-status').textContent=e.message;if(/unavailable|expired/.test(e.message)){clearInterval(pollTimer);connection=null;persistConnection();connectionUI();}}finally{pollBusy=false;}}
function beginPolling(){clearInterval(pollTimer);pollTimer=setInterval(poll,1000);persistConnection();connectionUI();}
function online(action){return async()=>{if(A.isBlocked())return;const beetle=picked()[0];if(!beetle)return;const button=$(action==='create'?'room-create':'room-join');button.disabled=true;$('room-status').textContent=action==='create'?'Creating your room code…':'Sending your beetle…';try{const token=secureToken(),code=$('room-join-code').value;const data=await request(action,{code,token,beetle:G.packet(beetle,{anonymous:true})});connection={code:data.room.code,token,role:action==='create'?'host':'guest',room:data.room};seenMatch=0;startPending=false;match=null;resetCelebration();applyRoom(data.room);beginPolling();A.toast(action==='create'?'Room code created. Share it with one classmate.':'Beetle sent to your classmate’s table.');}catch(e){$('room-status').textContent=e.message;button.disabled=false;}};}
$('sumo-start').onclick=()=>{if(connection||A.isBlocked())return;newMatch(picked(),crypto.getRandomValues(new Uint32Array(1))[0]);};
$('sumo-pause').onclick=()=>{if(match?.shared)return;paused=!paused;$('sumo-pause').textContent=paused?'Resume match':'Pause match';$('sumo-ring').classList.toggle('resting',paused);};
$('sumo-speed').onchange=()=>{playback=Number($('sumo-speed').value);};for(const id of ['sumo-a','sumo-b'])$(id).onchange=()=>{if(match&&!match.done){A.toast('These choices apply to the next match.');return;}match=null;preview();};
$('compare-open').onclick=compare;$('sumo-guide-open').onclick=()=>{$('sumo-trait-guide').innerHTML=Object.entries(descriptions).map(([k,d])=>'<h3>'+G.byKey[k].label+'</h3><p>'+d+'</p>').join('');$('sumo-guide').showModal();};
$('export-beetle-json').onclick=()=>exportBeetle(false);$('export-beetle-doc').onclick=()=>exportBeetle(true);$('family-tree-open').onclick=family;
for(const [button,corner] of [['specimen-red','sumo-a'],['specimen-blue','sumo-b']])$(button).onclick=()=>{if(connection){A.toast('Leave the shared table before changing local corners.');return;}$(corner).value=A.getSelected();match=null;preview();$('inspector').close();$('sumo-section').scrollIntoView({block:'start',behavior:'smooth'});};
$('family-tree-content').onclick=e=>{const b=e.target.closest('[data-tree]');if(b)A.inspect(b.dataset.tree);};
$('import-beetle').onclick=()=>$('beetle-file').click();$('beetle-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1024*1024)throw Error('Choose a single-beetle file under 1 MB. Use Open tank file for a whole experiment.');const b=A.addBeetle(parseFile(await f.text()));$('sumo-a').value=b.id;A.toast('Imported '+b.id+' with its exact genes and appearance.');A.inspect(b.id);}catch(error){A.toast(error.message);}e.target.value='';};
$('match-log-open').onclick=log;$('match-json').onclick=()=>download('Pattern-Lab-sumo-matches.json',JSON.stringify({model:'SUMO2',matches:A.getState().matchHistory||[]},null,2));
$('match-log-content').onclick=e=>{const b=e.target.closest('[data-replay]');if(!b)return;if(connection){A.toast('Leave the shared table before replaying a local record.');return;}const record=A.getState().matchHistory[Number(b.dataset.replay)];if(!record?.participants)return;newMatch(record.participants.map(p=>G.validatePacket(p).beetle),record.seed,false,record.version);$('match-log').close();};
$('room-create').onclick=online('create');$('room-join').onclick=online('join');$('room-copy').onclick=async()=>{try{await navigator.clipboard.writeText($('room-code').value);A.toast('Room code copied.');}catch{$('room-code').select();A.toast('Select and copy the code.');}};
$('room-start').onclick=async()=>{syncStartButton();if($('room-start').disabled)return;const active=connection;startPending=true;syncStartButton();try{const data=await request('start',{code:active.code,token:active.token});applyRoom(data.room);}catch(e){if(connection===active)$('room-status').textContent=e.message;}finally{if(connection===active){startPending=false;syncStartButton();}}};
$('room-leave').onclick=async()=>{const old=connection;connection=null;startPending=false;clearInterval(pollTimer);persistConnection();connectionUI();seenMatch=0;refresh();if(match?.shared){match=null;preview();}if(old?.role==='host')try{await request('close',{code:old.code,token:old.token});}catch{}$('room-status').textContent='You left the shared table. Your beetles are still safe in your tank.';};
window.addEventListener('pattern-state',refresh);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&connection)poll();});
refresh();requestAnimationFrame(animate);
try{const previous=JSON.parse(sessionStorage.getItem('pattern-sumo-connection')||'null');if(previous&&A.getState().settings.allowSumo!==false&&!A.isBlocked()&&/^[A-Z2-9]{8}$/.test(previous.code)&&/^[A-Za-z0-9_-]{43}$/.test(previous.token)&&['host','guest'].includes(previous.role)){connection=previous;beginPolling();poll();}}catch{}
})();
